package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.*;

import java.util.Arrays;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import java.util.stream.IntStream;

import org.eclipse.rdf4j.sail.lmdb.LmdbQueryMemoryManager;
import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelRuntime;
import org.junit.jupiter.api.Test;

class NativeWideDistinctReadmissionTest {
	private static long[] row(int id) {
		long[] result = new long[30];
		Arrays.fill(result, id);
		return result;
	}

	private static NativeBudgetedWideDistinct distinct(LmdbQueryMemoryManager.QueryLedger ledger) {
		return new NativeBudgetedWideDistinct(IntStream.range(0, 30).toArray(), null, ledger,
				new NativeCancellationToken());
	}

	@Test
	void competingQueryStealsReleasedWorkspaceWithoutCorruptingEitherOwner() throws Exception {
		var manager = LmdbQueryMemoryManager.createForTesting(12_000, 12_000);
		var stolen = new AtomicReference<LmdbQueryMemoryManager.Reservation>();
		try (var firstLedger = manager.openQuery(); var secondLedger = manager.openQuery();
				var first = distinct(firstLedger); var second = distinct(secondLedger);
				var executor = Executors.newSingleThreadExecutor()) {
			for (int i = 1; i <= 100; i++) assertTrue(first.add(row(i)));
			for (int i = 201; i <= 300; i++) assertTrue(second.add(row(i)));
			assertFalse(first.primitiveActive());
			assertFalse(second.primitiveActive());
			long firstBefore = firstLedger.usedBytes();
			try {
				assertThrows(KernelRuntime.AllocationDeniedException.class, () -> first.clear(() -> {
					assertEquals(firstBefore - 4096, firstLedger.usedBytes(), "workspace must already be released");
					try {
						stolen.set(executor.submit(() -> secondLedger.reserve(4096, null)).get(10, TimeUnit.SECONDS));
					} catch (Exception failure) {
						throw new AssertionError(failure);
					}
					assertNotNull(stolen.get(), "competing query must actually claim the released workspace");
				}));
				assertEquals(0, firstLedger.usedBytes(), "refused owner must release its structural claim immediately");
				assertThrows(IllegalStateException.class, () -> first.add(row(3)));
				assertThrows(IllegalStateException.class, first::clear);
				first.close();
				assertFalse(second.add(row(202)), "other query's previous membership survives");
				assertTrue(second.add(row(500)), "other query remains usable under the same budget");
				assertTrue(manager.peakUsedBytes() <= 12_000);
			} finally {
				if (stolen.get() != null) stolen.get().close();
			}
		}
		assertEquals(0, manager.usedBytes());
	}

	@Test
	void transitionCallbackFailureClosesOwnerAndPreservesPrimaryException() {
		var manager = LmdbQueryMemoryManager.createForTesting(7_000, 7_000);
		try (var ledger = manager.openQuery(); var distinct = distinct(ledger)) {
			assertTrue(distinct.add(row(1)));
			assertFalse(distinct.primitiveActive());
			var expected = new IllegalArgumentException("injected transition failure");
			assertSame(expected, assertThrows(IllegalArgumentException.class,
					() -> distinct.clear(() -> { throw expected; })));
			assertEquals(0, ledger.usedBytes());
			assertThrows(IllegalStateException.class, () -> distinct.add(row(1)));
			distinct.close();
			assertEquals(0, ledger.usedBytes());
		}
		assertEquals(0, manager.usedBytes());
	}
}
